#include <iostream>
constexpr int square(int x) { return x * x; }
template <int N> struct PowerOfTwo { static constexpr int value = 2 * PowerOfTwo<N-1>::value; };
template <> struct PowerOfTwo<0> { static constexpr int value = 1; };
int main() {
  constexpr int a = square(5); // compile time calculation
  constexpr int b = PowerOfTwo<10>::value; // compile time calculation
  std::cout << "Square of 5: " << a << std::endl;
  std::cout << "2^10: " << b << std::endl;
  return 0;
}
